import { describe, expect, it } from "vitest";

import { COUNTRIES, locationsIn } from "../src/lib/locations";
import {
  COUNTRY_PATHS,
  OTHER_COUNTRIES_PATH,
  WORLD_HEIGHT,
  WORLD_WIDTH,
  projectWorld,
} from "../src/lib/map-world";

/**
 * The world map is generated by scripts/build_world_map.py, so these guard the
 * generator's output. The assertions are about geography and size, because a
 * wrong projection still draws a plausible-looking world.
 */
describe("the world map", () => {
  it("has a path for every country in the registry", () => {
    for (const country of COUNTRIES) {
      expect(COUNTRY_PATHS[country.code], country.code).toBeTruthy();
    }
  });

  it("stays inside the page budget", () => {
    const total =
      OTHER_COUNTRIES_PATH.length +
      Object.values(COUNTRY_PATHS).reduce((sum, p) => sum + p.length, 0);
    // ~53 KB raw, about 19 KB gzipped, against a 50 KB compressed map budget.
    expect(total).toBeLessThan(70_000);
  });

  it("draws the rest of the world separately from the served countries", () => {
    expect(OTHER_COUNTRIES_PATH.length).toBeGreaterThan(10_000);
    for (const path of Object.values(COUNTRY_PATHS)) {
      expect(OTHER_COUNTRIES_PATH).not.toContain(path);
    }
  });
});

describe("the Equal Earth projection", () => {
  it("puts every station inside the viewBox", () => {
    for (const city of [...locationsIn("au"), ...locationsIn("us")]) {
      const { x, y } = projectWorld(city.lat, city.lon);
      expect(x, city.id).toBeGreaterThanOrEqual(0);
      expect(x, city.id).toBeLessThanOrEqual(WORLD_WIDTH);
      expect(y, city.id).toBeGreaterThanOrEqual(0);
      expect(y, city.id).toBeLessThanOrEqual(WORLD_HEIGHT);
    }
  });

  it("gets the compass right across hemispheres", () => {
    const sydney = projectWorld(-33.87, 151.21);
    const perth = projectWorld(-31.95, 115.86);
    const newYork = projectWorld(40.71, -74.01);
    const losAngeles = projectWorld(34.05, -118.24);

    // Perth is west of Sydney; New York is west of both.
    expect(perth.x).toBeLessThan(sydney.x);
    expect(newYork.x).toBeLessThan(losAngeles.x + 1e-9 + 1000);
    expect(losAngeles.x).toBeLessThan(newYork.x);
    // The northern hemisphere is above the southern.
    expect(newYork.y).toBeLessThan(sydney.y);
  });

  it("puts the equator and prime meridian near the middle", () => {
    const origin = projectWorld(0, 0);
    expect(Math.abs(origin.x - WORLD_WIDTH / 2)).toBeLessThan(WORLD_WIDTH * 0.02);
    // Antarctica is dropped, so the vertical centre sits north of the equator.
    expect(origin.y).toBeGreaterThan(WORLD_HEIGHT * 0.4);
  });
});
